findPanelElement.code:
const panel = document.querySelector('.ms-Panel-content');
const els = panel.querySelectorAll('*');
for (const el of els) {
  const ownText = Array.from(el.childNodes).filter(n => n.nodeType === 3).map(n => n.textContent.trim()).join('');
  if (ownText === 'Target Text') { el.click(); break; }
}

